%[text] %[text:anchor:T_D48C173C] # High Voltage Battery - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Random current
BatteryHV_SystemThermal_params
target_subsystem = "BatteryHV_SystemThermal_refsub";

model_name = "HarnessModel_BatteryHV";
load_system(model_name)
%[text] Test conditions
LoadInputs_BatteryHV_Random

t = batteryHV.Input_LoadCurrent_TimePoints.value("s");
f = batteryHV.Input_LoadCurrent_Data.value("A");
fig = figure; %[output:8e91f229]
fig.Position(3:4) = [900 300];  % width height %[output:8e91f229]
bevutil1.SignalUtil.plotLookupTable1D(t, f, InterpolationInterval=0.5, ParentAxes=axes(fig)) %[output:8e91f229]
xlabel("Time (s)") %[output:8e91f229]
ylabel("A") %[output:8e91f229]
title("Load current") %[output:8e91f229]
%[text] Initial conditions
initial.hvBattery_SOC_pct = 50;
initial.hvBattery_SOC_normalized = initial.hvBattery_SOC_pct / 100;

tmp_batt_charge = HighVoltageBatteryTool1.getAmpereHourRating( ...
  Capacity = simscape.Value(batteryHV.nominalCapacity_kWh, "kWh"), ...
  Voltage = simscape.Value(batteryHV.nominalVoltage_V, "V"), ...
  StateOfCharge = initial.hvBattery_SOC_normalized );

initial.hvBattery_Charge_Ahr = value(tmp_batt_charge, "Ah");
disp(initial) %[output:292b1a17]
%[text] Simulation
sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, model_name + "/Inputs", ReferencedSubsystem = "Inputs_BatteryHV_refsub");
sim_in = setBlockParameter(sim_in, model_name + "/High Voltage Battery", ReferencedSubsystem = target_subsystem);
sim_in = setModelParameter(sim_in, StopTime = string(t(end)));
disp("Stop time: " + t(end)) %[output:7c9a8a23]
applyToModel(sim_in)
sim_out = sim(sim_in);

logged_signals = extractTimetable(sim_out.logsout);

BatteryHV_plotResults(Timetable = logged_signals); %[output:8dea1b14]
